/**
 * The stop status a signed status webhook carried, saved by the channel so
 * the watch it fires can wake without reading a status that may lag.
 */
import * as z from "zod/v4";
const stopSignal = z.object({
    status: z.enum(["finished", "error", "expired"]),
    at: z.string().datetime(),
});
function stopSignalKey(agentId) {
    return `cloud-agents/stops/${agentId}`;
}
/** Save `status` when it is a stop; other statuses leave the last stop in place. */
export async function saveStopSignal(kv, agentId, webhook) {
    const signal = stopSignal.safeParse({
        status: webhook.status.toLowerCase(),
        at: webhook.timestamp,
    });
    if (signal.success) {
        await kv.put(stopSignalKey(agentId), signal.data);
    }
}
/** The saved stop of `agentId` at or after `since`, or undefined. */
export async function readStopSignal(kv, agentId, since) {
    const saved = stopSignal.safeParse(await kv.get(stopSignalKey(agentId)));
    return saved.success && Date.parse(saved.data.at) >= since ? saved.data : undefined;
}
